import itertools
def search(p):
 A=p['input']; O=p['output']; h=next(i for i,r in enumerate(A) if len(set(r))==1 and r[0]!=7);w=A[0].index(A[h][0]); A=[r[:w] for r in A[:h]]
 H=len(O);W=len(O[0]);sol=[]
 for sy,sx in itertools.product([1,-1],repeat=2):
  for ay,ax in itertools.product(range(h),range(w)):
   for py,px in itertools.product([0,1],repeat=2):
    ok=True
    for y in range(H):
     for x in range(W):
      yy=(sy*y+py*(x//w)+ay)%h;xx=(sx*x+px*(y//h)+ax)%w
      if A[yy][xx]!=O[y][x]:ok=False;break
     if not ok:break
    if ok:sol.append((sy,sx,ay,ax,py,px))
 return sol
